style.css:
body {
  background-color: #ffe6f0;
  font-family: 'Arial', sans-serif;
  text-align: center;
  padding: 50px;
}

h1 {
  color: #ff1493;
  font-size: 60px;
  text-shadow: 2px 2px #ffb6c1;
  margin-bottom: 30px;
}

p {
  color: #ff69b4;
  font-size: 24px;
  line-height: 1.5;
}

button {
  background-color: #ff69b4;
  color: white;
  font-size: 20px;
  padding: 15px 30px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s;
}

button:hover {
  background-color: #ff1493;
  transform: scale(1.1);
}
